// self(b) = 2 (only "a;b" ends in b); inclusive(b) = 3 + 2 + 1 = 6
// flame graph, root at the bottom, children in alphabetical order:
//   [c 3]          [b 1]
//   [b    5     ][d  1 ]
//   [a        6        ]
static Map<String, Long> inclusive(List<Sample> samples) {
    Map<String, Long> result = new HashMap<>();
    for (Sample s : samples) {
        for (String frame : new HashSet<>(s.frames())) {   // once per sample
            result.merge(frame, s.count(), Long::sum);
        }
    }
    return result;
}

